package com.alpharip.staffmod.IncidentPostMortemBoard; public final class IncidentTimelineEntry { private String id,actor,description; private long timestamp; public IncidentTimelineEntry(){} public IncidentTimelineEntry(String i,String a,String d,long t){id=req(i);actor=req(a);description=req(d);if(t<=0)throw new IllegalArgumentException("Timestamp must be positive");timestamp=t;} public String getId(){return id;} public String getActor(){return actor;} public String getDescription(){return description;} public long getTimestamp(){return timestamp;} private static String req(String s){if(s==null||s.trim().isEmpty())throw new IllegalArgumentException("Required value missing");return s.trim();} }